//! Local-only witness. Never supply real saves in CI. Emits bounded typed frames to captured stdout.
use hkia_save_core::{archive::MAX_ARCHIVE,session::{ProductSession,Stamp,Request,Command,Payload,Row,Domain},projection::DetailKind,abi::{MAGIC,dispatch_frame,encode_reply}};
use std::io::{self,Read,Write};
fn frame(st:Stamp,id:u64,op:u8,tail:&[u8])->Vec<u8>{let mut v=Vec::new();v.extend(MAGIC);v.push(op);v.extend(id.to_le_bytes());v.extend(st.runtime);v.extend(st.generation.to_le_bytes());v.extend(st.revision.to_le_bytes());v.push(u8::from(st.source.is_some()));v.extend(st.source.unwrap_or([0;32]));v.extend(tail);v}
fn keep(frames:&mut Vec<Vec<u8>>,total:&mut usize,r:Vec<u8>)->Result<(),()>{*total=total.checked_add(r.len()).ok_or(())?;if *total>16*1024*1024{return Err(())}frames.push(r);Ok(())}
fn run()->Result<(),()> {if std::env::args().nth(1).as_deref()!=Some("--private-session"){return Err(())}let mut raw=Vec::new();io::stdin().take((MAX_ARCHIVE+1) as u64).read_to_end(&mut raw).map_err(|_|())?;let mut s=ProductSession::new([1;16]).map_err(|_|())?;let f=frame(s.stamp(),1,1,&[1]);let reply=dispatch_frame(&mut s,&f,Some(raw)).map_err(|_|())?;if reply.get(77)!=Some(&1){return Err(())}let mut total_bytes=reply.len();let mut frames=vec![reply];let mut id=1u64;let mut parents=Vec::new();for d in [Domain::SlotAchievement,Domain::SlotCounter,Domain::CollectionHistory,Domain::Celebration,Domain::AccountAchievement,Domain::AccountCounter,Domain::Inventory,Domain::DeprecatedCollection]{let mut offset=0u32;loop{id+=1;let expected=s.stamp();let r=s.dispatch(Request{id,expected,command:Command::IndexPage{domain:d,offset,limit:128}});let p=match &r.result{Ok(Payload::Page(p))=>p,_=>return Err(())};let total=p.total;let n=p.rows.len() as u32;for row in &p.rows{match row{Row::Slot(m)if d==Domain::SlotCounter=>{parents.push((DetailKind::CounterValues,m.id));parents.push((DetailKind::CounterGuids,m.id));},Row::Celebration(c)=>parents.push((DetailKind::CelebrationGuids,c.id)),_=>{}}}if n>128||offset+n>total||n==0&&offset<total{return Err(())}keep(&mut frames,&mut total_bytes,encode_reply(r))?;offset+=n;if offset==total{break}}}for(kind,parent)in parents{let mut offset=0;loop{id+=1;let expected=s.stamp();let r=s.dispatch(Request{id,expected,command:Command::DetailPage{kind,parent,offset,limit:128}});let p=match &r.result{Ok(Payload::Detail(p))=>p,_=>return Err(())};let total=p.total;let n=p.rows.len() as u32;if n>128||offset+n>total||n==0&&offset<total{return Err(())}keep(&mut frames,&mut total_bytes,encode_reply(r))?;offset+=n;if offset==total{break}}}let f=frame(s.stamp(),id+1,2,&[]);let r=dispatch_frame(&mut s,&f,None).map_err(|_|())?;if r.get(77)!=Some(&1)||r.get(78)!=Some(&2){return Err(())}keep(&mut frames,&mut total_bytes,r)?;let mut o=io::BufWriter::new(io::stdout().lock());for r in frames{o.write_all(&(r.len()as u32).to_le_bytes()).map_err(|_|())?;o.write_all(&r).map_err(|_|())?;}o.flush().map_err(|_|())}
fn main(){if run().is_err(){std::process::exit(1)}}
